27: /// @brief RAII guard: unsubscribes current task from TWDT for scope lifetime,
28: ///        resubscribes on destruction. Matches OTAUpdateManager pattern
29: ///        (OTAUpdateManager.cpp:666-671).
30: /// @note The TWDT is a starvation detector. A task parked in select() during
31: ///       a network fetch is not the failure mode it exists to catch — that is
32: ///       already answered by the idle tasks. Unsubscription is safe here because:
33: ///       (1) DeadlineToken provides cooperative cancel,
34: ///       (2) Layer 1 bounds the transport at ~15s,
35: ///       (3) Layer 4 escalates via shutdown(fd) if the fetch overruns.
36: ///       See ADR: TWDT Supervision Strategy.
37: /// @warning Proxy-feeding (esp_timer calling esp_task_wdt_reset()) does NOT work:
38: ///          esp_task_wdt_reset() acts on the CALLING task's handle. From a timer
39: ///          context it either fails with ESP_ERR_NOT_FOUND or feeds the wrong entry.
40: struct TwdtFetchGuard {
41:     explicit TwdtFetchGuard() {
42:         esp_task_wdt_delete(NULL);
43:     }
44:     ~TwdtFetchGuard() {
45:         esp_task_wdt_add(NULL);
46:         esp_task_wdt_reset();
47:     }
48:     TwdtFetchGuard(const TwdtFetchGuard&) = delete;
49:     TwdtFetchGuard& operator=(const TwdtFetchGuard&) = delete;
50: };
