58: class FetchGuard {
59: public:
60:     FetchGuard(IDataSource* source, FetchContext& ctx, FrameworkSecureClient* secureClient, WiFiClient* plainClient)
61:         : _timer(nullptr) {
62:         bool useTls = source ? source->requiresTls() : true;
63:         
64:         if (useTls && secureClient) {
65:             secureClient->stop();
66:             secureClient->applyDeadline(ctx.deadline);
67:             ctx.client = secureClient;
68:         } else if (plainClient) {
69:             plainClient->stop();
70:             plainClient->setConnectionTimeout(
71:                 std::min(ctx.deadline.remainingMs(), FetchContext::CONNECT_TIMEOUT_MS));
72:             ctx.client = plainClient;
73:         }
74:         
75:         _escCtx.client = ctx.client;
76:         
77:         esp_timer_create_args_t timerArgs = {};
78:         timerArgs.callback = [](void* arg) {
79:             auto* e = static_cast<EscalationCtx*>(arg);
80:             int fd = e->client ? e->client->fd() : -1;
81:             if (fd >= 0) {
82:                 shutdown(fd, SHUT_RDWR);
83:                 ESP_LOGW(TAG, "Fetch deadline exceeded — socket shutdown forced");
84:             } else {
85:                 ESP_LOGE(TAG, "Fetch deadline exceeded with no framework socket in flight — "
86:                               "source is not using ctx.client and cannot be interrupted");
87:             }
88:         };
89:         timerArgs.arg = &_escCtx;
90:         timerArgs.name = "fetch_deadline";
91: 
92:         uint32_t remaining = ctx.deadline.remainingMs();
93:         if (remaining > 0) {
94:             esp_timer_create(&timerArgs, &_timer);
95:             esp_timer_start_once(_timer, (uint64_t)remaining * 1000);
96:         }
97:     }
98: 
99:     ~FetchGuard() {
100:         if (_timer) {
101:             esp_timer_stop(_timer);
102:             esp_timer_delete(_timer);
103:             _timer = nullptr;
104:         }
105:     }
106: 
107: private:
108:     esp_timer_handle_t _timer;
109:     EscalationCtx _escCtx;
110:     TwdtFetchGuard _wdtGuard;
111: };
