175: void DataManager::begin() {
176:     _jobQueue = xQueueCreate(JOB_QUEUE_DEPTH, sizeof(DataJobEntry*));
177:     if (!_jobQueue) {
178:         ESP_LOGE(TAG, "Failed to create job queue");
179:     }
180: 
181: #ifdef ESP_PLATFORM
182:     _secureClient = new (std::nothrow) FrameworkSecureClient();
183:     if (_secureClient) {
184:         _secureClient->useDefaultCertBundle();
185:     } else {
186:         ESP_LOGE(TAG, "Failed to allocate FrameworkSecureClient");
187:     }
188:     _plainClient = new (std::nothrow) WiFiClient();
189:     if (!_plainClient) {
190:         ESP_LOGE(TAG, "Failed to allocate WiFiClient");
191:     }
192: #endif
193: 
194: 
195:     // Create worker task with configurable DRAM stack — safe for TLS-heavy data sources.
196:     // DRAM (not PSRAM) is required because SPI flash operations (used by some
197:     // data sources) assert when the task stack is in PSRAM.
198:     ESP_LOGI(TAG, "Creating worker task (stack=%u, priority=5, core=any, DRAM)",
199:              (unsigned)_workerStackSize);
200:     BaseType_t result = xTaskCreate(
201:         workerTaskLoop,
202:         "DataManager",
203:         _workerStackSize,
204:         this,
205:         5,
206:         &_workerTask
207:     );
208:     if (result != pdPASS) {
209:         ESP_LOGE(TAG, "Failed to create DataManager worker task");
210:         _workerTask = nullptr;
211:     }
