218: bool DataManager::queueDataJob(std::function<void(const FetchContext&)> job, const DataJobOptions& options) {
219:     if (!_jobQueue || !job) return false;
220: 
221:     DataJobEntry* entry = new (std::nothrow) DataJobEntry{
222:         std::move(job),
223:         options
224:     };
225:     if (!entry) {
226:         ESP_LOGE(TAG, "Failed to allocate job entry for '%s'", options.tag);
227:         return false;
228:     }
229: 
230:     if (xQueueSend(_jobQueue, &entry, 0) != pdTRUE) {
231:         ESP_LOGW(TAG, "Job queue full — dropping '%s' (%d pending)",
232:                  options.tag, (int)getQueuedJobCount());
233:         delete entry;
234:         return false;
235:     }
236: 
237:     ESP_LOGD(TAG, "Queued data job: '%s' (urgent=%s)", options.tag,
238:              options.urgent ? "yes" : "no");
239: 
240:     if (_workerTask) {
241:         xTaskNotifyGive(_workerTask);
242:     }
243: 
244:     return true;
245: }
