252: void DataManager::drainJobs(bool urgentOnly) {
253:     if (!_jobQueue) return;
254: 
255:     // Snapshot current queue depth to bound this drain pass (F8).
256:     // Jobs enqueued during execution are deferred to the next iteration.
257:     size_t maxDrain = (size_t)uxQueueMessagesWaiting(_jobQueue);
258:     if (maxDrain == 0) return;
259: 
260:     // Collect non-matching entries to re-queue after the scan (F5).
261:     // Stack-allocated — bounded by JOB_QUEUE_DEPTH.
262:     DataJobEntry* deferred[JOB_QUEUE_DEPTH];
263:     size_t deferredCount = 0;
264:     size_t drained = 0;
265: 
266:     DataJobEntry* entry = nullptr;
267:     while (drained < maxDrain && xQueueReceive(_jobQueue, &entry, 0) == pdTRUE) {
268:         drained++;
269:         if (urgentOnly && !entry->options.urgent) {
270:             // Not urgent — defer for later pass
271:             deferred[deferredCount++] = entry;
272:             continue;
273:         }
274: 
275:         ESP_LOGD(TAG, "Executing data job: '%s'", entry->options.tag);
276: 
277:         uint32_t jobStart = getCurrentTimeMs();
278: 
279:         DeadlineToken token(jobStart + FetchContext::FETCH_TOTAL_TIMEOUT_MS,
280:                             [](void* ctx) -> uint32_t { return static_cast<DataManager*>(ctx)->getCurrentTimeMs(); },
281:                             this);
282:         FetchContext ctx{token};
283: #ifdef ESP_PLATFORM
284:         FetchGuard fg(nullptr, ctx,
285:                       entry->options.requiresTls ? _secureClient : nullptr,
286:                       entry->options.requiresTls ? nullptr : _plainClient);
287: #endif
288: 
289:         entry->job(ctx);
290:         if (ctx.deadline.isExpired()) {
291:             ESP_LOGW(TAG, "Data job '%s' exceeded deadline", entry->options.tag);
292:         }
293: 
294:         uint32_t elapsed = getCurrentTimeMs() - jobStart;
295:         if (entry->options.warnAfterMs > 0 && elapsed > entry->options.warnAfterMs) {
296:             ESP_LOGW(TAG, "Data job '%s' took %lu ms (warn threshold: %lu ms)",
297:                      entry->options.tag, (unsigned long)elapsed,
298:                      (unsigned long)entry->options.warnAfterMs);
299:         }
300: 
301:         delete entry;
302:     }
303: 
304:     // Re-queue deferred entries, preserving their order relative to each other.
305:     // Caveat: jobs enqueued by another task *during* this drain are already at
306:     // the back of the queue, so they will run before these deferred entries.
307:     // Strict global FIFO is therefore not guaranteed across a drain boundary.
308:     for (size_t i = 0; i < deferredCount; i++) {
309:         if (xQueueSend(_jobQueue, &deferred[i], 0) != pdTRUE) {
310:             ESP_LOGW(TAG, "Failed to re-queue deferred job '%s' — dropping",
311:                      deferred[i]->options.tag);
312:             delete deferred[i];
313:         }
314:     }
315: }
