344: void DataManager::requestPriorityFetch(IDataSource* source) {
345:     if (!source) return;
346:     ESP_LOGI(TAG, "Priority fetch requested for source: %s", source->getSourceName());
347:     MutexLock lock(_registryMutex);
348: 
349:     for (auto& r : _registry) {
350:         if (r.source == source) {
351:             r.priorityRequested = true;
352: 
353:             // Wake the worker task to process the priority fetch immediately
354:             if (_workerTask) {
355:                 xTaskNotifyGive(_workerTask);
356:             }
357:             break;
358:         }
359:     }
