362: // ---------------------------------------------------------------------------
363: // Health state machine (#128)
364: //
365: // Failure is a state, not a reset. Every transition below is driven by the
366: // UpdateStatus the source returned — these codes already distinguish cases the
367: // scheduler should treat differently, and the distinction was previously unused.
368: // ---------------------------------------------------------------------------
369: void DataManager::recordFetchOutcome(SourceRecord& r, UpdateStatus status, uint32_t nowMs) {
370:     SourceHealthState oldState = r.state;
371: 
372:     // lastStatus is stamped for ALL statuses — surfaces can show *why* nothing is happening
373:     r.lastStatus = status;
374: 
375:     // lastAttemptMs is NOT stamped for Skipped — it was not a genuine attempt
376:     if (status != UpdateStatus::Skipped) r.lastAttemptMs = nowMs;
377: 
378:     switch (status) {
379:     case UpdateStatus::Skipped:
380:         return;   // health, backoff, everSucceeded all untouched
381: 
382:     case UpdateStatus::Success:
383:     case UpdateStatus::NoChange:
384:         // Recovery is unconditional: one success clears the whole failure history,
385:         // including from Quarantined (the probe worked) and Suspended (a priority
386:         // fetch after the user fixed the credentials). A later failure therefore
387:         // starts a fresh series from the base delay, not from the old ceiling.
388:         r.state                = SourceHealthState::Healthy;
389:         r.consecutiveFailures  = 0;
390:         r.currentBackoffMs     = 0;
391:         r.nextAttemptMs        = 0;
392:         r.backoffActive        = false;
393:         r.backoffFromRateLimit = false;
394:         r.lastSuccessMs        = nowMs;
395:         r.everSucceeded        = true;
396: 
397:         if (oldState != r.state) {
398:             r._hasPendingHealthTransition = true;
399:             r._healthPayload = { r.source->getSourceName(), r.state };
400:         }
401:         return;
402: 
403:     case UpdateStatus::AuthError:
404:         // Terminal until someone intervenes. Credentials do not fix themselves,
405:         // so retrying on a timer only burns the radio and the remote's rate limit.
406:         // Exit is resetSourceHealth() or an explicit priority fetch.
407:         r.state             = SourceHealthState::Suspended;
408:         if (r.consecutiveFailures < UINT16_MAX) r.consecutiveFailures++;
409:         r.currentBackoffMs  = 0;
410:         r.nextAttemptMs     = 0;
411:         r.backoffActive     = false;
412:         
413:         if (oldState != r.state) {
414:             r._hasPendingHealthTransition = true;
415:             r._healthPayload = { r.source->getSourceName(), r.state };
416:         }
417: 
418:         ESP_LOGE(TAG, "Source '%s' SUSPENDED after auth failure — will not retry until reset",
419:                  r.source->getSourceName());
420:         return;
421: 
422:     case UpdateStatus::RateLimited: {
423:         // The peer is reachable and answering; we are simply asking too often.
424:         // Back off, but do not count it toward quarantine — this is not a fault
425:         // in the source, and quarantining a working peer would be wrong.
426:         //
427:         // A change of cause restarts the series: a source that has been rate-
428:         // limited up to the ceiling should not inherit that delay for its first
429:         // genuine failure, and vice versa. Without this the two policies interfere,
430:         // and one FetchError on a peer that was answering thirty seconds ago
431:         // quarantines it immediately.
432:         uint32_t effectiveCap = std::max(r.source ? r.source->getMaxBackoffMs() : HEALTH_BACKOFF_CAP_MS, HEALTH_BACKOFF_BASE_MS);
433:         r.currentBackoffMs = (!r.backoffActive || !r.backoffFromRateLimit)
434:             ? HEALTH_BACKOFF_BASE_MS
435:             : std::min(r.currentBackoffMs * 2, effectiveCap);
436:         r.nextAttemptMs        = nowMs + r.currentBackoffMs;
437:         r.backoffActive        = true;
438:         r.backoffFromRateLimit = true;
439:         if (r.state == SourceHealthState::Healthy || r.state == SourceHealthState::Unknown) {
440:             r.state = SourceHealthState::Degraded;
441:         }
442:         
443:         if (oldState != r.state) {
444:             r._hasPendingHealthTransition = true;
445:             r._healthPayload = { r.source->getSourceName(), r.state };
446:         }
447: 
448:         ESP_LOGW(TAG, "Source '%s' rate-limited — backing off %lu ms",
449:                  r.source->getSourceName(), (unsigned long)r.currentBackoffMs);
450:         return;
451:     }
452: 
453:     case UpdateStatus::FetchError:
454:     case UpdateStatus::ParseError:
455:     default:
456:         break;
457:     }
458: 
459:     // --- Genuine failure: count it, back off, quarantine at the ceiling ---
460:     // Saturating: at ceiling probes an unsaturated uint16_t would take
461:     // ~682 days to wrap, but wrapping to 0 would read as "healthy" to a consumer.
462:     if (r.consecutiveFailures < UINT16_MAX) r.consecutiveFailures++;
463:     uint32_t effectiveCap = std::max(r.source ? r.source->getMaxBackoffMs() : HEALTH_BACKOFF_CAP_MS, HEALTH_BACKOFF_BASE_MS);
464:     r.currentBackoffMs = (!r.backoffActive || r.backoffFromRateLimit)
465:         ? HEALTH_BACKOFF_BASE_MS
466:         : std::min(r.currentBackoffMs * 2, effectiveCap);
467:     r.nextAttemptMs        = nowMs + r.currentBackoffMs;
468:     r.backoffActive        = true;
469:     r.backoffFromRateLimit = false;
470: 
471:     // Quarantined is not "given up" — it is "probing at the backoff cap",
472:     // so an unreachable peer that comes back is picked up without
473:     // anyone touching the device. Quarantining is triggered after
474:     // QUARANTINE_FAILURE_THRESHOLD consecutive failures, decoupled from backoff cap.
475:     r.state = (r.consecutiveFailures >= QUARANTINE_FAILURE_THRESHOLD)
476:         ? SourceHealthState::Quarantined
477:         : SourceHealthState::Degraded;
478: 
479:     if (oldState != r.state) {
480:         r._hasPendingHealthTransition = true;
481:         r._healthPayload = { r.source->getSourceName(), r.state };
482:     }
483: 
484:     ESP_LOGW(TAG, "Source '%s' %s (status=%d, %u consecutive) — next attempt in %lu ms%s",
485:              r.source->getSourceName(),
486:              r.state == SourceHealthState::Quarantined ? "QUARANTINED" : "degraded",
487:              (int)status, (unsigned)r.consecutiveFailures,
488:              (unsigned long)r.currentBackoffMs,
489:              r.everSucceeded ? "" : " (has never connected)");
490: }
