496:     out.consecutiveFailures = r.consecutiveFailures;
497:     out.lastAttemptMs       = r.lastAttemptMs;
498:     out.lastSuccessMs       = r.lastSuccessMs;
499:     out.nextAttemptMs       = r.nextAttemptMs;
500:     out.currentBackoffMs    = r.currentBackoffMs;
501:     out.everSucceeded       = r.everSucceeded;
