529: void DataManager::resetSourceHealth(IDataSource* source) {
530:     if (!source) return;
531:     MutexLock lock(_registryMutex);
532:     for (auto& r : _registry) {
533:         if (r.source == source) {
534:             ESP_LOGI(TAG, "Health reset for source: %s", source->getSourceName());
535:             // Unknown in both branches, not Healthy-if-it-ever-worked. Healthy is
536:             // documented as "last attempt succeeded", and after a reset following
537:             // a string of failures the last attempt did not succeed — reporting
538:             // Healthy would tell the portal the source is fine when nothing has
539:             // been verified. Reset means "clear the penalty box and try again",
540:             // which is exactly Unknown. everSucceeded is preserved, so the
541:             // never-connected distinction survives.
542:             r.state                = SourceHealthState::Unknown;
543:             r.lastStatus           = UpdateStatus::Success;  // no verdict; see SourceHealth::lastStatus
544:             r.consecutiveFailures  = 0;
545:             r.currentBackoffMs     = 0;
546:             r.nextAttemptMs        = 0;
547:             r.backoffActive        = false;
548:             r.backoffFromRateLimit = false;
549:             return;
550:         }
551:     }
552: }
