561: void DataManager::processNext() {
562: #ifdef ESP_PLATFORM
563:     // On target the worker task drives this loop. Calling from any other
564:     // task would run blocking network I/O on the caller (e.g. loopTask)
565:     // without supervision, and corrupt the caller's TWDT state via
566:     // startFetchWatchdog()/stopFetchWatchdog(). Refuse outright. See #156.
567:     if (xTaskGetCurrentTaskHandle() != _workerTask) {
568:         ESP_LOGE(TAG, "processNext() called from %s — native/test only, "
569:                  "the worker task drives this loop on target",
570:                  pcTaskGetName(NULL));
571:         return;
572:     }
573: #endif
574:     drainJobs(true);
575:     executeLoop();
576:     drainJobs(false);
577: }
