582: void DataManager::workerTaskLoop(void* param) {
583:     DataManager* manager = static_cast<DataManager*>(param);
584: 
585:     // Register with Task Watchdog Timer — this is a long-running worker loop
586:     // that must feed the watchdog periodically to avoid triggering a reset.
587:     esp_task_wdt_add(NULL);
588: 
589:     TickType_t lastWatermarkLog = 0;
590: 
591:     while (true) {
592:         manager->drainJobs(true);
593:         manager->executeLoop();
594:         manager->drainJobs(false);
595: 
596:         // Feed the watchdog after each fetch cycle
597:         esp_task_wdt_reset();
598: 
599:         // Periodic stack watermark telemetry — log every 60s to avoid spam.
600:         // Data gathered here informs future stack reduction / PSRAM migration.
601:         // Uses raw tick counts with pdMS_TO_TICKS to avoid multiply overflow.
602:         TickType_t now = xTaskGetTickCount();
603:         if (lastWatermarkLog == 0 || (now - lastWatermarkLog) >= pdMS_TO_TICKS(60000)) {
604:             UBaseType_t hwm = uxTaskGetStackHighWaterMark(nullptr);
605:             ESP_LOGI(TAG, "Worker stack high water mark: %lu B free (of %lu)",
606:                      (unsigned long)(hwm * sizeof(StackType_t)),
607:                      (unsigned long)manager->_workerStackSize);
608:             lastWatermarkLog = now;
609:         }
610: 
611:         ulTaskNotifyTake(pdTRUE, pdMS_TO_TICKS(100)); // sleep between loop checks to avoid starving other tasks
612:     }
613: 
614:     // Note: This loop never exits under normal operation. If it ever did,
615:     // we would call esp_task_wdt_delete(NULL) before vTaskDelete.
616: }
617: 
618: void DataManager::executeLoop() {
619:     // NOTE: _appRunning is deliberately NOT a blanket early return.
620:     //
621:     // It used to be, and that silently voided two guarantees. A source that backs
622:     // a startup precondition forms a circle with the state machine: the precondition blocks
623:     // RUNNING, RUNNING enables fetching, and fetching is what would satisfy the
624:     // precondition. Once such a source failed into Quarantined, Application regressed to
625:     // CONFIGURING and cleared _appRunning — so the 15-minute self-healing probe
626:     // never ran again, the gate could never re-satisfy, and _appRunning could
627:     // never return to true. The device sat there permanently, and the peer coming
628:     // back changed nothing because there was no probe left to notice.
629:     //
630:     // The same early return sat above the priorityRequested check, so
631:     // requestPriorityFetch() was inert in precisely the state where a source
632:     // needs recovering — the user corrects the address in the portal, we request
633:     // a fetch, and nothing happens.
634:     //
635:     // The gate is now applied per-source, below both escape hatches.
636:     // _appRunning was deliberately removed. See the NOTE above for the full rationale.
637:     // This constant preserves the per-source gating logic below (fetchesWhileConfiguring)
638:     // without the global blanket early return that caused the circular-dependency deadlock.
639:     // The variable reads as "all sources allowed" and the per-source checks provide the
640:     // actual gating. If a global gate is ever needed again, it should be an atomic bool
641:     // driven by Application state transitions, not a removed setter.
642:     const bool appRunning = true;
643: 
644:     MutexLock lock(_registryMutex);
645:     if (_registry.empty()) return;
646: 
647:     uint32_t now = getCurrentTimeMs();
648:     int bestIndex = -1;
649:     bool foundPriority = false;
650:     PriorityTier bestTier = PriorityTier::Low;
651: 
652:     for (size_t i = 0; i < _registry.size(); ++i) {
653:         auto& r = _registry[i];
654: 
655:         // Handle explicit priority requests.
656:         // A priority fetch deliberately ignores backoff, health state AND the
657:         // app-running gate: it represents a person asking for this now, usually
658:         // straight after correcting the thing that was broken. It is the manual
659:         // recovery path for a source no timer will retry, so it must work in
660:         // CONFIGURING — that is the state a broken source puts the device into.
661:         if (r.priorityRequested) {
662:             bestIndex = i;
663:             foundPriority = true;
664:             break; // Immediate selection
665:         }
666: 
667:         // Scheduled fetching is gated on RUNNING, except for sources that
668:         // explicitly opt out because they back a config gate (see
669:         // IDataSource::fetchesWhileConfiguring).
670:         if (!appRunning && !r.source->fetchesWhileConfiguring()) continue;
671: 
672:         // Health backoff gate (#128). Suspended sources are excluded outright —
673:         // they are not on a timer at all.
674:         if (r.state == SourceHealthState::Suspended) continue;
675: 
676:         // Rollover-safe comparison. millis() wraps at ~49.7 days, which is
677:         // ordinary uptime here. An absolute `now < nextAttemptMs` breaks in both
678:         // directions across a wrap: a deadline computed just before one wraps to a
679:         // small value and skips backoff entirely, and afterwards a small `now`
680:         // against a large pre-wrap deadline blocks the source for up to ~49 days.
681:         // Signed difference is the same idiom the `due` computation below uses.
682:         if (r.backoffActive && (int32_t)(now - r.nextAttemptMs) < 0) continue;
683: 
684:         // Handle scheduled execution based on interval and tier
685:         bool due = (r.lastFetchTimeMs == 0) || (now - r.lastFetchTimeMs >= r.source->getUpdateIntervalMs());
686: 
687:         if (due && !foundPriority) {
688:             // Smaller priority enum values indicate higher priority (HIGH = 0, LOW = 2)
689:             if (bestIndex == -1 || r.source->getPriorityTier() < bestTier) {
690:                 bestIndex = i;
691:                 bestTier = r.source->getPriorityTier();
692:             }
693:         }
694:     }
695: 
696:     if (bestIndex != -1) {
697:         auto& r = _registry[bestIndex];
698:         r.priorityRequested = false;
699: 
700:         // Extract the target source before releasing the lock
701:         IDataSource* fetchTarget = r.source;
702:         ESP_LOGD(TAG, "Selected source for fetch: %s", fetchTarget->getSourceName());
703: 
704:         // Unlock mutex during fetch to prevent holding the lock during potentially long network calls
705:         if (_registryMutex) xSemaphoreGive(_registryMutex);
706: 
707:         // --- Execute the fetch cycle ---
708:         uint32_t fetchStart = getCurrentTimeMs();
709: 
710:         DeadlineToken token(fetchStart + FetchContext::FETCH_TOTAL_TIMEOUT_MS,
711:                             [](void* ctx) -> uint32_t { return static_cast<DataManager*>(ctx)->getCurrentTimeMs(); },
712:                             this);
713:         FetchContext ctx{token};
714: #ifdef ESP_PLATFORM
715:         FetchGuard fg(fetchTarget, ctx, _secureClient, _plainClient);
716: #endif
717: 
718:         UpdateStatus result = fetchTarget->fetchUpdate(ctx);
719:         if (ctx.deadline.isExpired()) {
720:             ESP_LOGW(TAG, "Fetch for '%s' exceeded deadline — marking as FetchError",
721:                      fetchTarget->getSourceName());
722:         }
723:         if (ctx.deadline.isExpired() && result == UpdateStatus::Success) {
724:             result = UpdateStatus::FetchError;
725:         }
726: 
727:         uint32_t fetchDuration = getCurrentTimeMs() - fetchStart;
728:         if (fetchDuration > 15000) {
729:             ESP_LOGW(TAG, "fetchUpdate() for source '%s' took %lu ms — consider reducing client timeout",
730:                      fetchTarget->getSourceName(), (unsigned long)fetchDuration);
731:         }
732: 
733:         // Re-acquire mutex to update state
734:         if (_registryMutex) xSemaphoreTake(_registryMutex, portMAX_DELAY);
735: 
736:         bool publishHealth = false;
737: 
738:         // Ensure source is still registered before updating tracking data.
739:         // A source can be unregistered while its fetch is in flight, in which
740:         // case the outcome is simply discarded along with its health.
741:         for (auto& r2 : _registry) {
742:             if (r2.source == fetchTarget) {
743:                 // One clock read for both: lastFetchTimeMs gates the next
744:                 // scheduling pass and lastAttemptMs gates backoff, and there is no
745:                 // reason for them to disagree by the width of two millis() calls.
746:                 uint32_t completedAt = getCurrentTimeMs();
747:                 r2.lastFetchTimeMs = completedAt;
748:                 recordFetchOutcome(r2, result, completedAt);
749:                 
750:                 if (r2._hasPendingHealthTransition) {
751:                     publishHealth = true;
752:                     _publishPayload = r2._healthPayload;
753:                     r2._hasPendingHealthTransition = false;
754:                 }
755:                 break;
756:             }
757:         }
758:         
759:         // Temporarily release lock to publish event safely
760:         if (_registryMutex) xSemaphoreGive(_registryMutex);
761: 
762:         if (publishHealth && _eventBus) {
763:             _eventBus->publish(ApplicationEvents::DATA_SOURCE_HEALTH, &_publishPayload);
764:         }
765: 
766:         // Re-acquire lock to maintain MutexLock destructor balance
767:         if (_registryMutex) xSemaphoreTake(_registryMutex, portMAX_DELAY);
768:     }
769: }
